_AUDIO_CACHE_DIR = os.path.join(os.path.dirname(__file__), "audio_cache")
os.makedirs(_AUDIO_CACHE_DIR, exist_ok=True)


def _normalize_tts_cache_text(text):
    """Normalize spoken text so equivalent phrases map to one audio cache key."""
    clean = str(text or '')
    clean = unicodedata.normalize('NFD', clean)
    clean = ''.join(ch for ch in clean if unicodedata.category(ch) != 'Mn')
    clean = clean.lower()
    clean = re.sub(r'[^a-zäöüõšž0-9\s]', ' ', clean)
    clean = re.sub(r'\s+', ' ', clean).strip()
    return clean


def _build_audio_cache_path(text, prefix, extension, speaker=None, api_speed=None, lang=None):
    """Create a deterministic cache filename for generated speech."""
    cache_text = _normalize_tts_cache_text(text)
    payload = f"{prefix}|{cache_text}|{speaker or ''}|{api_speed if api_speed is not None else ''}|{lang or ''}"
    digest = hashlib.sha256(payload.encode("utf-8")).hexdigest()[:16]
    return os.path.join(_AUDIO_CACHE_DIR, f"{prefix}_{digest}.{extension}")


def _play_audio_file(audio_path):
    """Play an audio file using playsound when available."""
    if not audio_path or not os.path.exists(audio_path):
        return False

    try:
        playsound(audio_path)
        return True
    except Exception as exc:
        print(f"Could not play audio via playsound: {exc}")
        return False


TOPICS_PATH = os.path.join(os.path.dirname(__file__), "topics.json")


def load_topics_from_json():
    if not os.path.exists(TOPICS_PATH):
        return [], {}

    try:
        with open(TOPICS_PATH, "r", encoding="utf-8") as f:
            payload = json.load(f)
        return payload.get("topicList", []), payload.get("topicContent", {})
    except Exception as exc:
        print(f"Warning: could not load topics from {TOPICS_PATH}: {exc}")
        return [], {}


