def estonian_tts_tartunlp(text, speaker="mari", api_speed=1.0, output_filename="tartunlp_output.wav"):
    """
    Generates Estonian speech from text using the TartuNLP Text-to-Speech API.

    Args:
        text (str): The Estonian text to convert to speech.
        speaker (str, optional): The speaker voice. Defaults to "mari".
                                 Available speakers include: "mari", "tambet", "liivika", "kalev",
                                 "külli", "meelis", "albert", "indrek", "vambola", "eva".
        api_speed (float, optional): Speaking speed for the API. Defaults to 1.0.
                                     Values typically between 0.5 (slower) and 2.0 (faster).
        output_filename (str, optional): The filename to save the generated audio.
                                         Defaults to "tartunlp_output.wav".
    Returns:
        bool: True if speech was generated and saved successfully, False otherwise.
    """
    api_url = "https://api.tartunlp.ai/text-to-speech/v2"
    payload = {
        "text": text,
        "speaker": speaker,
        "speed": api_speed
    }
    headers = {
        "Content-Type": "application/json"
    }

    use_cache = output_filename == "tartunlp_output.wav"
    target_path = _build_audio_cache_path(text, "tartunlp", "wav", speaker=speaker, api_speed=api_speed) if use_cache else os.path.abspath(output_filename)

    if os.path.exists(target_path):
        print(f"Using cached audio file: {target_path}")
        _play_audio_file(target_path)
        return True

    print(f"Attempting to generate speech via TartuNLP API: \"{text}\" (Speaker: {speaker}, Speed: {api_speed:.2f})")

    try:
        response = requests.post(api_url, json=payload, headers=headers, timeout=60) # Increased to 60-second timeout
        response.raise_for_status()  # Raises an HTTPError for bad responses (4XX or 5XX)

        os.makedirs(os.path.dirname(target_path), exist_ok=True)

        with open(target_path, 'wb') as f:
            f.write(response.content)
        print(f"Speech audio saved to {target_path}")
        _play_audio_file(target_path)
        return True

    except requests.exceptions.HTTPError as e:
        print(f"HTTP error occurred with TartuNLP API: {e.response.status_code} - {e}")
        print(f"Response content from API: {e.response.text}")
    except requests.exceptions.RequestException as e:
        print(f"Error connecting to TartuNLP API: {e}")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    
    return False

def english_tts_gtts(text, lang='en', use_slow=False, output_filename="gtts_english_output.mp3"):
    """
    Generates English speech from text using the gTTS library (Google Translate's TTS).
    Does not require an API key for basic use.

    Args:
        text (str): The English text to convert to speech.
        lang (str, optional): The language code. Defaults to 'en' for English.
        use_slow (bool, optional): Whether to use gTTS's slow speed. Defaults to False.
        output_filename (str, optional): The filename to save the generated audio.
                                         Defaults to "gtts_english_output.mp3".
    Returns:
        bool: True if speech was generated and saved successfully, False otherwise.
    """
    try:
        use_cache = output_filename == "gtts_english_output.mp3"
        target_path = _build_audio_cache_path(text, "gtts", "mp3", lang=lang, api_speed=use_slow) if use_cache else os.path.abspath(output_filename)

        if os.path.exists(target_path):
            print(f"Using cached audio file: {target_path}")
            _play_audio_file(target_path)
            return True

        print(f"Attempting to generate English speech via gTTS: \"{text[:70]}...\" (Slow: {use_slow})")
        tts = gTTS(text=text, lang=lang, slow=use_slow)
        os.makedirs(os.path.dirname(target_path), exist_ok=True)
        tts.save(target_path)
        print(f'English audio content (gTTS) saved to file "{target_path}"')
        _play_audio_file(target_path)
        return True

    except Exception as e:
        print(f"An error occurred with gTTS: {e}")
        return False

def get_current_tts_speeds():
    """Gets the current speed settings from the GUI scale."""
    tartunlp_api_speed = 1.0  # Default API speed for TartuNLP
    gtts_slow = False       # Default for gTTS (normal speed)

    if _w and hasattr(_w, 'speed') and _w.speed: # Check if GUI scale widget exists
        try:
            scale_value = _w.speed.get() # Value from 0.0 to 100.0
            # Map scale value (0-100) to TartuNLP API speed (0.5-2.0)
            # 0 -> 0.5, 33 -> ~1.0, 100 -> 2.0
            tartunlp_api_speed = 0.5 + (scale_value / 100.0) * 1.5
            
            # Determine if gTTS should be slow (e.g., if scale is <= 30, as 33 is normal)
            if scale_value <= 30: # Threshold for "slow" on the 0-100 scale
                gtts_slow = True
        except tk.TclError:
            print("Warning: Could not get speed from GUI scale. Using default TTS speeds.")
    return tartunlp_api_speed, gtts_slow

