def _perform_qa_playback(topic_name, qa_index, tartunlp_speed_to_use, gtts_slow_to_use):
    """
    Plays the Estonian question and optionally its English translation for a given topic and index.
    This is used by both "Start Question" and "Next Question".
    """
    global _qa_thread_active
    try:
        if not topic_name or topic_name not in topicContent or not topicContent[topic_name]:
            _safe_gui_update(_update_assistant_text_threaded, "Topic content not found or is empty.\n")
            return
        
        conversation_lines = topicContent[topic_name]
        if not (0 <= qa_index < len(conversation_lines)):
            _safe_gui_update(_update_assistant_text_threaded, f"Invalid question index: {qa_index}.\n")
            return

        current_line = conversation_lines[qa_index]
        estonian_question = current_line[0]
        english_question_translation = current_line[2] # Get English translation

        _safe_gui_update(_update_assistant_text_threaded, f"Question {qa_index + 1} of {len(conversation_lines)} for topic: {topic_name}\n\n")

        _safe_gui_update(_update_assistant_text_threaded, f"Estonian Q: {estonian_question}\n")
        estonian_tts_tartunlp(estonian_question, speaker="mari", api_speed=tartunlp_speed_to_use)

        # Check the state of the "Enable English TTS" checkbox
        enable_english_val = 0
        if _w and hasattr(_w, 'enableEnglishVar'): # Ensure _w and its attribute exist
            enable_english_val = _w.enableEnglishVar.get()

        if enable_english_val == 1:
            _safe_gui_update(_update_assistant_text_threaded, f"Translate Q: {english_question_translation}\n")
            english_tts_gtts(english_question_translation, use_slow=gtts_slow_to_use)

        _safe_gui_update(_update_assistant_text_threaded, "\n--- Click NEXT for the next question or START for a new topic/restart. ---\n")

    except Exception as e:
        print(f"Error during Q&A playback thread: {e}")
        _safe_gui_update(_update_assistant_text_threaded, f"Error during question playback: {e}\n")
    finally:
        _qa_thread_active = False
        _set_qa_buttons_state(True) # Re-enable Q&A buttons
        sys.stdout.flush()



def _trigger_qa_playback():
    """Initiates the playback of a single question in a new thread."""
    global _qa_thread_active
    if _qa_thread_active: # Should ideally be checked by caller, but as a safeguard
        print("Q&A playback already in progress.")
        return

    if not _active_topic_for_qa or _current_qa_index < 0:
        _w.assistantText.insert(tk.END, "No active topic or question index.\n")
        return

    current_tartunlp_speed, current_gtts_slow = get_current_tts_speeds() # Get speeds before starting thread

    _qa_thread_active = True
    _set_qa_buttons_state(False) # Disable Q&A buttons

    thread = threading.Thread(target=_perform_qa_playback, args=(_active_topic_for_qa, _current_qa_index, current_tartunlp_speed, current_gtts_slow))
    thread.daemon = True
    thread.start()

def on_start_question_click():
    global _qa_thread_active, _active_topic_for_qa, _current_qa_index
    if _qa_thread_active:
        print("Q&A task is already in progress.")
        _w.assistantText.insert(tk.END, "Question presentation already in progress...\n")
        _w.assistantText.see(tk.END)
        return

    _w.assistantText.delete('1.0',tk.END)

    # Check if random topic selection is enabled
    if _w.che70.get() == 1 and topicList: # che70 is the IntVar for enableRandmTopic
        random_topic = random.choice(topicList)
        _w.TCombobox1.set(random_topic)
        _w.assistantText.insert(tk.END, f"Random topic selected: {random_topic}\n")
        _w.assistantText.see(tk.END)

    current_topic_name = _w.TCombobox1.get()
    if not current_topic_name or current_topic_name not in topicContent:
        _w.assistantText.insert(tk.END, "Please select a valid topic from the list first.\n")
        _w.assistantText.see(tk.END)
        print("Start Question: No valid topic selected or topic not in content.")
        sys.stdout.flush()
        return
    
    _active_topic_for_qa = current_topic_name
    _current_qa_index = 0  # Start with the first question (index 0)

    conversation_lines = topicContent.get(_active_topic_for_qa, [])
    if not conversation_lines or _current_qa_index >= len(conversation_lines):
        _w.assistantText.insert(tk.END, f"No questions available for topic: {_active_topic_for_qa}.\n")
        _w.assistantText.see(tk.END)
        print(f"Start Question: No questions (e.g., at index 0) for topic {_active_topic_for_qa}.")
        # Reset state
        _active_topic_for_qa = None
        _current_qa_index = -1
        sys.stdout.flush()
        return

    print(f"Starting questions for topic: {_active_topic_for_qa}, starting at index: {_current_qa_index}")
    _trigger_qa_playback()


def on_next_question_click():
    _w.assistantText.delete('1.0', tk.END) # Clear text area at the beginning

    global _shadowing_active_and_waiting, _shadowing_proceed_event, _play_memorization_thread_active
    # Check if this "NEXT" click is for continuing shadowing
    if _shadowing_active_and_waiting and _play_memorization_thread_active:
        print("NEXT click received for shadowing. Signaling task to proceed.")
        _shadowing_proceed_event.set()
        # The _play_memorization_task will handle disabling the NEXT button and updating text.
        return # Bypass Q&A "NEXT" logic

    # --- If not shadowing, proceed with Q&A "NEXT" logic ---
    global _qa_thread_active, _active_topic_for_qa, _current_qa_index
    if _qa_thread_active:
        print("Q&A task is already in progress.")
        _w.assistantText.insert(tk.END, "Question presentation already in progress...\n")
        _w.assistantText.see(tk.END)
        return
    
    # Text area already cleared at the top of the function.
    
    if not _active_topic_for_qa or _current_qa_index == -1:
        _w.assistantText.insert(tk.END, "Please click 'START QUESTION' to begin a topic first.\n")
        _w.assistantText.see(tk.END)
        print("Next Question: No active topic. Please start one.")
        sys.stdout.flush()
        return

    # _current_qa_index holds the index of the question just played.
    # Increment by 1 to get the next sequential question.
    _current_qa_index += 1
    
    conversation_lines = topicContent.get(_active_topic_for_qa, [])
    if _current_qa_index >= len(conversation_lines):
        _w.assistantText.insert(tk.END, f"End of questions for topic: {_active_topic_for_qa}.\nSelect 'START QUESTION' for this or another topic.\n")
        _w.assistantText.see(tk.END)
        print(f"Next Question: End of questions for topic {_active_topic_for_qa}.")
        # Reset state
        _active_topic_for_qa = None
        _current_qa_index = -1
        sys.stdout.flush()
        return
    print(f"Next Question for topic: {_active_topic_for_qa}, new index: {_current_qa_index}")
    sys.stdout.flush()
    _trigger_qa_playback()


def _safe_gui_update(callback, *args):
    """Safely schedules a GUI update using root.after, handling potential TclErrors."""
    if _w and _w.top:
        try:
            # Use a lambda to ensure args are passed correctly if callback is a method
            _w.top.after(0, lambda c=callback, a=args: c(*a))
        except tk.TclError as e:
            print(f"GUI update failed (window likely closing): {e}")
        except Exception as e: # Catch other potential errors during callback scheduling
            print(f"Unexpected error scheduling GUI update: {e}")
    else:
        print("GUI elements not available for update (window likely closing or not initialized).")

def _update_assistant_text_threaded(text_to_insert):
    """Helper function to be called by _safe_gui_update for assistantText."""
    if _w and _w.assistantText:
        _w.assistantText.insert(tk.END, text_to_insert)
        # update_idletasks might not be strictly necessary when called via `after`
        # but can ensure immediate visual feedback if there are many updates.
        _w.assistantText.update_idletasks()
        _w.assistantText.see(tk.END)

def _set_widget_state_threaded(widget, enable):
    """Helper function to be called by _safe_gui_update for button state."""
    if widget:
        state = tk.NORMAL if enable else tk.DISABLED
        widget.config(state=state)

def _set_qa_buttons_state(enable):
    """Enables or disables all Q&A control buttons."""
    if _w: # Ensure GUI elements are available
        buttons_to_manage = [
            getattr(_w, 'questionButton', None),
            getattr(_w, 'nextQuestion', None),
            getattr(_w, 'repeatQuestion', None),
            getattr(_w, 'giveAnswerButton', None)
        ]
        for button in buttons_to_manage:
            if button:
                _safe_gui_update(_set_widget_state_threaded, button, enable)


def _play_memorization_task(current_topic_name, tartunlp_speed_to_use, gtts_slow_to_use, is_shadowing_enabled):
    """The actual work of playing memorization, to be run in a separate thread."""
    global _play_memorization_thread_active, _current_memorization_line_data, _shadowing_active_and_waiting
    try:
        _safe_gui_update(_update_assistant_text_threaded, f"Playing memorization for topic: {current_topic_name}\n\n")

        conversation_lines_for_selected_topic = topicContent[current_topic_name]

        for conversation_line in conversation_lines_for_selected_topic:
            # The stop button logic is removed, so this check might be less critical
            # but good to keep if a future stop mechanism is added.
            if not _play_memorization_thread_active: # Check if STOP was pressed
                break

            estonian_question = conversation_line[0]
            estonian_answer = conversation_line[1]
            english_question_translation = conversation_line[2]
            english_answer_translation = conversation_line[3]
            
            # Store current line data for potential repeat
            _current_memorization_line_data = (estonian_question, estonian_answer, english_question_translation, english_answer_translation)

            _safe_gui_update(_update_assistant_text_threaded, f"Estonian Q: {estonian_question}\n")
            estonian_tts_tartunlp(estonian_question, speaker="mari", api_speed=tartunlp_speed_to_use)

            _safe_gui_update(_update_assistant_text_threaded, f"Estonian A: {estonian_answer}\n")
            estonian_tts_tartunlp(estonian_answer, speaker="vesta", api_speed=tartunlp_speed_to_use)

            # Read the current state of the checkbox in each iteration
            enable_english_var_value = _w.enableEnglishVar.get()

            if enable_english_var_value == 1:
                _safe_gui_update(_update_assistant_text_threaded, f"Translate Q: {english_question_translation}\n")
                english_tts_gtts(english_question_translation, use_slow=gtts_slow_to_use)

                _safe_gui_update(_update_assistant_text_threaded, f"Translate A: {english_answer_translation}\n")
                english_tts_gtts(english_answer_translation, use_slow=gtts_slow_to_use)
            
            _safe_gui_update(_update_assistant_text_threaded, "---\n")

            # If shadowing is NOT enabled, then we pause and wait for NEXT/RPT.
            if not is_shadowing_enabled: # Note the 'not'
                _safe_gui_update(_update_assistant_text_threaded, "Shadowing: Paused. Click NEXT to continue or RPT MEMO to repeat.\n")
                _safe_gui_update(_set_widget_state_threaded, _w.nextQuestion, True) # Enable NEXT button
                _safe_gui_update(_set_widget_state_threaded, _w.repeatMemoButton, True) # Enable RPT MEMO
                
                _shadowing_proceed_event.clear()
                _shadowing_proceed_event.wait() # Wait for NEXT click

                # If the main playback was stopped (e.g., by a future stop button or error), exit loop
                if not _play_memorization_thread_active:
                    break

                _safe_gui_update(_set_widget_state_threaded, _w.nextQuestion, False) # Disable NEXT button after proceeding
                _safe_gui_update(_set_widget_state_threaded, _w.repeatMemoButton, False) # Disable RPT MEMO
                _safe_gui_update(_update_assistant_text_threaded, "Shadowing: Resuming...\n")

        _safe_gui_update(_update_assistant_text_threaded, "\nMemorization playback complete.\n")

    except Exception as e:
        print(f"Error during memorization playback thread: {e}")
        _safe_gui_update(_update_assistant_text_threaded, f"Error during playback: {e}\n")
    finally:
        _play_memorization_thread_active = False
        _shadowing_active_and_waiting = False # Reset shadowing state
        _current_memorization_line_data = None # Clear stored line data
        _shadowing_proceed_event.set() # Ensure any waiting event.wait() is unblocked if exiting

        _safe_gui_update(_set_widget_state_threaded, _w.playMemorizationButton, True)
        _safe_gui_update(_set_widget_state_threaded, _w.autoShadowing, True) # Re-enable shadowing checkbox
        _safe_gui_update(_set_widget_state_threaded, _w.repeatMemoButton, False) # Ensure RPT MEMO is disabled
        _safe_gui_update(_set_widget_state_threaded, _w.stopMemoButton, False) # Ensure STOP button is disabled
        _safe_gui_update(_set_widget_state_threaded, _w.enableEnglishCheckbox, True)
        
        # Re-enable all Q&A buttons to their normal idle state
        _set_qa_buttons_state(True)
        sys.stdout.flush()

def on_play_memorization_click():
    global _play_memorization_thread_active, _shadowing_active_and_waiting, _shadowing_proceed_event
    if _play_memorization_thread_active:
        print("Memorization playback is already in progress.")
        # Optionally, update GUI to inform user
        _w.assistantText.insert(tk.END, "Playback already in progress...\n")
        _w.assistantText.see(tk.END)
        return

    _w.assistantText.delete('1.0',tk.END)

    # Check if random topic selection is enabled
    if _w.che70.get() == 1 and topicList: # che70 is the IntVar for enableRandmTopic
        random_topic = random.choice(topicList)
        _w.TCombobox1.set(random_topic)
        _w.assistantText.insert(tk.END, f"Random topic for memorization: {random_topic}\n")
        _w.assistantText.see(tk.END)

    current_topic_name = _w.TCombobox1.get()

    if not current_topic_name or current_topic_name not in topicContent:
        # This direct update is fine as it's before starting a thread
        _w.assistantText.insert(tk.END, "Please select a valid topic from the list first.\n")
        _w.assistantText.see(tk.END)
        print("Play Memorization: No valid topic selected or topic not in content.")
        sys.stdout.flush()
        return

    is_shadowing_checked = _w.che67.get() == 1 # che67 is the IntVar for autoShadowing

    print(f"Play Memorization button clicked for topic: {current_topic_name}")
    sys.stdout.flush()

    current_tartunlp_speed, current_gtts_slow = get_current_tts_speeds() # Get speeds before starting thread

    _play_memorization_thread_active = True
    # If shadowing is NOT checked (is_shadowing_enabled is False), then we are in step-by-step mode
    # and _shadowing_active_and_waiting should be true to allow NEXT/RPT_MEMO.
    # If shadowing IS checked (is_shadowing_enabled is True), then play continuously, so _shadowing_active_and_waiting is false.
    if not is_shadowing_checked: # This means we want to pause
        _shadowing_active_and_waiting = True
    else:
        _shadowing_active_and_waiting = False

    _safe_gui_update(_set_widget_state_threaded, _w.playMemorizationButton, False) # Disable play button
    _safe_gui_update(_set_widget_state_threaded, _w.autoShadowing, False) # Disable shadowing checkbox during playback

    # Disable Q&A buttons - NEXT is handled specially for shadowing by the task itself
    _safe_gui_update(_set_widget_state_threaded, _w.questionButton, False)
    _safe_gui_update(_set_widget_state_threaded, _w.repeatQuestion, False)
    _safe_gui_update(_set_widget_state_threaded, _w.giveAnswerButton, False)
    # NEXT button starts disabled; _play_memorization_task will enable it if shadowing and paused.
    _safe_gui_update(_set_widget_state_threaded, _w.nextQuestion, False)
    _safe_gui_update(_set_widget_state_threaded, _w.stopMemoButton, True) # Enable STOP button
    _safe_gui_update(_set_widget_state_threaded, _w.repeatMemoButton, False) # Ensure RPT MEMO is initially disabled


    # Create and start the worker thread
    thread = threading.Thread(target=_play_memorization_task, args=(current_topic_name, current_tartunlp_speed, current_gtts_slow, is_shadowing_checked))
    thread.daemon = True # Allows main program to exit even if this thread is running
    thread.start()

def on_stop_memo_click():
    global _play_memorization_thread_active, _shadowing_proceed_event
    if _play_memorization_thread_active:
        print("STOP MEMO button clicked. Halting memorization playback.")
        _play_memorization_thread_active = False # Signal the playback thread to stop
        _shadowing_proceed_event.set() # Unblock if paused in shadowing
        
        # Disable the stop button immediately. Other buttons are handled by the
        # finally block of _play_memorization_task.
        _safe_gui_update(_set_widget_state_threaded, _w.stopMemoButton, False)
        _w.assistantText.insert(tk.END, "Stopping memorization playback...\n")
        _w.assistantText.see(tk.END)
    sys.stdout.flush()

def _perform_single_memo_line_playback(line_data, tartunlp_speed_to_use, gtts_slow_to_use):
    """Plays a single stored memorization line (Est Q, Est A, Eng Q, Eng A)."""
    global _repeat_memo_thread_active
    try:
        _repeat_memo_thread_active = True
        # Temporarily disable NEXT and REPEAT MEMO during this specific playback
        _safe_gui_update(_set_widget_state_threaded, _w.nextQuestion, False)
        _safe_gui_update(_set_widget_state_threaded, _w.repeatMemoButton, False)
        # PLAY MEMORIZATION should already be disabled if we are in shadowing pause

        est_q, est_a, eng_q, eng_a = line_data

        _safe_gui_update(_update_assistant_text_threaded, f"Repeating...\nEstonian Q: {est_q}\n")
        estonian_tts_tartunlp(est_q, speaker="mari", api_speed=tartunlp_speed_to_use)

        _safe_gui_update(_update_assistant_text_threaded, f"Estonian A: {est_a}\n")
        estonian_tts_tartunlp(est_a, speaker="vesta", api_speed=tartunlp_speed_to_use)

        enable_english_val = _w.enableEnglishVar.get()
        if enable_english_val == 1:
            _safe_gui_update(_update_assistant_text_threaded, f"Translate Q: {eng_q}\n")
            english_tts_gtts(eng_q, use_slow=gtts_slow_to_use)

            _safe_gui_update(_update_assistant_text_threaded, f"Translate A: {eng_a}\n")
            english_tts_gtts(eng_a, use_slow=gtts_slow_to_use)
        
        _safe_gui_update(_update_assistant_text_threaded, "---\nShadowing: Paused. Click NEXT to continue or RPT MEMO to repeat.\n")

    except Exception as e:
        print(f"Error during single memo line repeat playback: {e}")
        _safe_gui_update(_update_assistant_text_threaded, f"Error during repeat: {e}\n")
    finally:
        _repeat_memo_thread_active = False
        # Re-enable NEXT and REPEAT MEMO as we are still in the paused shadowing state
        # Only if shadowing is still active and waiting (i.e., Play Memorization hasn't been stopped/completed)
        if _play_memorization_thread_active and _shadowing_active_and_waiting:
            _safe_gui_update(_set_widget_state_threaded, _w.nextQuestion, True)
            _safe_gui_update(_set_widget_state_threaded, _w.repeatMemoButton, True)
        sys.stdout.flush()

def on_repeat_memo_click():
    global _repeat_memo_thread_active, _current_memorization_line_data, _play_memorization_thread_active, _shadowing_active_and_waiting
    if _repeat_memo_thread_active:
        print("Repeat memo line playback already in progress.")
        return
    if not (_play_memorization_thread_active and _shadowing_active_and_waiting and _current_memorization_line_data):
        print("Cannot repeat memo: Not in shadowing pause or no line data.")
        return
    
    current_tartunlp_speed, current_gtts_slow = get_current_tts_speeds()
    thread = threading.Thread(target=_perform_single_memo_line_playback, args=(_current_memorization_line_data, current_tartunlp_speed, current_gtts_slow))
    thread.daemon = True
    thread.start()

def _perform_answer_playback(topic_name, qa_index, tartunlp_speed_to_use, gtts_slow_to_use):
    """Plays the Estonian answer and optionally its English translation for a given question."""
    global _qa_thread_active
    try:
        if not topic_name or topic_name not in topicContent or not topicContent[topic_name]:
            _safe_gui_update(_update_assistant_text_threaded, "Topic content not found or is empty for answer.\n")
            return
        
        conversation_lines = topicContent[topic_name]
        if not (0 <= qa_index < len(conversation_lines)):
            _safe_gui_update(_update_assistant_text_threaded, f"Invalid question index for answer: {qa_index}.\n")
            return

        current_line = conversation_lines[qa_index]
        estonian_answer = current_line[1]
        english_answer_translation = current_line[3]

        _safe_gui_update(_update_assistant_text_threaded, f"Answer for Question {qa_index + 1} of {len(conversation_lines)}:\n\n")

        _safe_gui_update(_update_assistant_text_threaded, f"Estonian A: {estonian_answer}\n")
        estonian_tts_tartunlp(estonian_answer, speaker="vesta", api_speed=tartunlp_speed_to_use)

        enable_english_val = 0
        if _w and hasattr(_w, 'enableEnglishVar'):
            enable_english_val = _w.enableEnglishVar.get()

        if enable_english_val == 1:
            _safe_gui_update(_update_assistant_text_threaded, f"Translate A: {english_answer_translation}\n")
            english_tts_gtts(english_answer_translation, use_slow=gtts_slow_to_use)

        _safe_gui_update(_update_assistant_text_threaded, "\n--- Ready for NEXT QUESTION or new topic. ---\n")

    except Exception as e:
        print(f"Error during answer playback thread: {e}")
        _safe_gui_update(_update_assistant_text_threaded, f"Error during answer playback: {e}\n")
    finally:
        _qa_thread_active = False
        _set_qa_buttons_state(True) # Re-enable Q&A buttons
        sys.stdout.flush()

def _trigger_answer_playback():
    """Initiates the playback of an answer in a new thread."""
    global _qa_thread_active
    if _qa_thread_active:
        print("TTS playback (question/answer) already in progress.")
        _w.assistantText.insert(tk.END, "Audio presentation already in progress...\n") # Inform user
        _w.assistantText.see(tk.END)
        return

    if not _active_topic_for_qa or _current_qa_index < 0:
        _w.assistantText.insert(tk.END, "No active question to provide an answer for.\n")
        _w.assistantText.see(tk.END)
        return

    current_tartunlp_speed, current_gtts_slow = get_current_tts_speeds() # Get speeds before starting thread

    _qa_thread_active = True
    _set_qa_buttons_state(False) # Disable Q&A buttons

    thread = threading.Thread(target=_perform_answer_playback, args=(_active_topic_for_qa, _current_qa_index, current_tartunlp_speed, current_gtts_slow))
    thread.daemon = True
    thread.start()

def on_give_answer_click():
    global _qa_thread_active, _active_topic_for_qa, _current_qa_index
    if _qa_thread_active: # Check before clearing text and other ops
        print("TTS task is already in progress (Give Answer).")
        _w.assistantText.insert(tk.END, "Audio presentation already in progress...\n")
        _w.assistantText.see(tk.END)
        return

    _w.assistantText.delete('1.0', tk.END)

    if not _active_topic_for_qa or _current_qa_index == -1:
        _w.assistantText.insert(tk.END, "No question active. Please click 'START QUESTION' or 'NEXT QUESTION' first to get an answer.\n")
        _w.assistantText.see(tk.END)
        print("Give Answer: No active question to give an answer for.")
        sys.stdout.flush()
        return

    print(f"Give Answer button clicked for topic: {_active_topic_for_qa}, question index: {_current_qa_index}")
    sys.stdout.flush()
    _trigger_answer_playback()

def on_repeat_question_click():
     _w.assistantText.delete('1.0',tk.END)
     # This function is purely for repeating the current Q&A question.
     # Shadowing logic should not be here.

     global _qa_thread_active, _active_topic_for_qa, _current_qa_index
     if _qa_thread_active:
         print("Q&A task is already in progress (Repeat).")
         _w.assistantText.insert(tk.END, "Question presentation already in progress...\n")
         _w.assistantText.see(tk.END)
         return

     if not _active_topic_for_qa or _current_qa_index == -1:
         _w.assistantText.insert(tk.END, "No question to repeat. Please click 'START QUESTION' or 'NEXT QUESTION' first.\n")
         _w.assistantText.see(tk.END)
         print("Repeat Question: No active question to repeat.")
         sys.stdout.flush()
         return

     # _active_topic_for_qa and _current_qa_index are already set to the current question.
     # We just need to trigger its playback again.
     print(f"Repeating question for topic: {_active_topic_for_qa}, index: {_current_qa_index}")
     sys.stdout.flush()
     _trigger_qa_playback()

def on_send_answer_click():
     _w.assistantText.delete('1.0',tk.END)
     print("Send Answer button clicked!")
     sys.stdout.flush()

def on_reset_speed_click():
    """Resets the TTS speed slider to the default normal speed."""
    if _w and hasattr(_w, 'speed') and _w.speed:
        default_speed_value = 33 # Corresponds to ~1.0 API speed for TartuNLP
        _w.speed.set(default_speed_value)
        print(f"TTS speed reset to normal (slider value: {default_speed_value}).")
        _w.assistantText.insert(tk.END, f"TTS speed reset to normal.\n")
        _w.assistantText.see(tk.END)
    sys.stdout.flush()